const embedRes = $input.first().json;
const vector = (embedRes.embeddings || [[]])[0];
const trigger = $('Execute Workflow Trigger').first().json;
const level = (trigger.level || '').trim();
const project = (trigger.project || '').trim();

const VALID_LEVELS = ['file', 'directory', 'project'];

const mustClauses = [];

if (level && VALID_LEVELS.includes(level)) {
  mustClauses.push({ key: 'metadata.level', match: { value: level } });
} else {
  // Default: search all summary levels (not raw chunks)
  mustClauses.push({ key: 'metadata.level', match: { any: ['file', 'directory', 'project'] } });
}

if (project) {
  mustClauses.push({ key: 'metadata.project', match: { value: project } });
}

const body = {
  vector: vector,
  limit: 6,
  with_payload: true,
  score_threshold: 0.4,
  filter: { must: mustClauses }
};

return [{ json: body }];

const results = $input.first().json.result || [];
const trigger = $('Execute Workflow Trigger').first().json;

if (results.length === 0) {
  return [{ json: { output: 'No summary results found for: "' + trigger.query + '"\nTip: try search_project_rag for implementation-level details.' } }];
}

const formatted = results.map(function(r, i) {
  const m = r.payload && r.payload.metadata ? r.payload.metadata : r.payload || {};
  const content = r.payload && r.payload.content ? r.payload.content : '';
  const level = m.level || 'unknown';
  const id = m.hierarchy_id || m.project || '?';
  const score = (r.score * 100).toFixed(0);
  return '[' + (i + 1) + '] [' + level.toUpperCase() + '] ' + id + ' (score: ' + score + '%)\n' + content;
}).join('\n\n');

return [{ json: { output: 'Project RAG summaries: "' + trigger.query + '" \u2014 ' + results.length + ' result(s)\n\n' + formatted } }];
